"""Issue #283 negative/structural tests; positive native decode is separate CI gate."""
import base64
import hashlib
import os
import json
import struct
import tempfile
import unittest
from pathlib import Path

from tools.ktx2_texture_admission import inspect_ktx2, convert_ktx2_glb

MAGIC = b'\xabKTX 20\xbb\r\n\x1a\n'
# Genuine 16x16 mipmapped BasisLZ KTX2 generated by Khronos KTX Software 4.4.2.
# Created from a simple original test texture, not a mocked compressed blob.
REAL_KHRONOS_KTX2 = base64.b64decode(
    ""
)
REAL_KTX_SHA256 = "be33e7a4f254a8c76492f6d00a9efd6ede08b6bd45d96e0aa4354e27ac0ffbb4"
REAL_KTX_BINARY_SHA256 = "2028e023a18e827e66362a9e184052f40192566b10f92655a337e2eb8ea0829b"


def ktx2(w=8, h=8, levels=1, space='srgb', model=163, data_size=4):
    # Framing-only specimen. Its compressed payload is deliberately NOT
    # decodable and MUST NEVER count as a real BasisU render test.
    dfd = bytearray(28)
    struct.pack_into('<I', dfd, 0, len(dfd))
    struct.pack_into('<H', dfd, 10, 24)
    dfd[12], dfd[13], dfd[14] = model, 1 if space == 'srgb' else 0, 2 if space == 'srgb' else 1
    index_end = 80 + 24 * levels
    scheme = 1 if model == 163 else 0
    sgd_offset = (index_end + len(dfd) + 7) & ~7 if scheme else 0
    sgd = bytes(20) if scheme else b''  # Structural only, not a real codebook
    level_begin = (sgd_offset + len(sgd)) if scheme else index_end + len(dfd)
    offsets = [level_begin + i * data_size for i in range(levels)]
    header = struct.pack('<12s13I2Q', MAGIC, 0, 1, w, h, 0, 0, 1, levels, scheme,
                         index_end, len(dfd), 0, 0, sgd_offset, len(sgd))
    index = b''.join(struct.pack('<QQQ', offset, data_size, 0 if scheme else data_size)
                     for offset in offsets)
    padding = bytes(sgd_offset - (index_end + len(dfd))) if scheme else b''
    return header + index + bytes(dfd) + padding + sgd + b'A' * (data_size * levels)


def budget(**override):
    return {'max_dimension': 4096, 'max_pixels': 4096 * 4096,
            'max_texture_bytes': 40 * 1024 * 1024,
            'max_lod_bytes': 128 * 1024 * 1024,
            'max_mip_bytes': 64 * 1024 * 1024, **override}


class TestKtx2Admission(unittest.TestCase):
    def test_real_khronos_v442_encoded_basisu_header_is_accepted(self):
        self.assertEqual(hashlib.sha256(REAL_KHRONOS_KTX2).hexdigest(), REAL_KTX_SHA256)
        entry = inspect_ktx2(REAL_KHRONOS_KTX2, budget(), 'srgb')
        self.assertEqual(entry['dimensions'], [16, 16])
        self.assertEqual(entry['mip_levels'], 5)
        self.assertEqual(entry['resident_decoded_bytes'], 1024)
        self.assertEqual(entry['mip_chain_decoded_bytes'], 1364)
        self.assertEqual(entry['supercompression'], 1)

    def test_bad_primaries_fail_even_when_transfer_matches_material(self):
        raw = bytearray(ktx2(space='linear', model=166))
        dfd_at = struct.unpack_from('<I', raw, 48)[0]
        raw[dfd_at + 13] = 1
        with self.assertRaisesRegex(ValueError, 'KTX2_COLOR_PRIMARIES'):
            inspect_ktx2(bytes(raw), budget(), 'linear')

    def test_real_khronos_uastc_linear_mipchain(self):
        binary = os.getenv('ARE_KHRONOS_KTX_BINARY')
        if not binary:
            self.skipTest('Real Khronos KTX binary required; dedicated KTX workflow runs this test')
        from PIL import Image
        import numpy as np
        import subprocess
        with tempfile.TemporaryDirectory(prefix='are-uastc-linear-') as folder:
            root = Path(folder)
            png = root / 'linear.png'
            data = np.zeros((16, 16, 4), dtype=np.uint8)
            data[:] = (20, 130, 210, 255)
            Image.fromarray(data, 'RGBA').save(png)
            ktx = root / 'linear-uastc.ktx2'
            out = root / 'decoded.png'
            subprocess.run([binary, 'create', '--format', 'R8G8B8A8_UNORM',
                            '--encode', 'uastc', '--assign-tf', 'linear',
                            '--assign-primaries', 'none', '--generate-mipmap',
                            str(png), str(ktx)], check=True, capture_output=True, timeout=50)
            subprocess.run([binary, 'validate', '--gltf-basisu', str(ktx)],
                           check=True, capture_output=True, timeout=50)
            item = inspect_ktx2(ktx.read_bytes(), budget(), 'linear')
            self.assertEqual(item['compression'], 'uastc_ldr')
            self.assertEqual(item['color_primaries'], 0)
            self.assertEqual(item['dimensions'], [16,16])
            self.assertGreaterEqual(item['mip_levels'], 1)
            subprocess.run([binary, 'extract', '--transcode', 'rgba8',
                            '--level', '0', str(ktx), str(out)],
                           check=True, capture_output=True, timeout=50)
            with Image.open(out) as decoded:
                self.assertEqual(decoded.size, (16,16))
                self.assertEqual(decoded.convert('RGBA').getpixel((0,0))[3], 255)

    def test_real_khronos_cli_transcodes_and_native_pbr_depth_is_preserved(self):
        binary = os.getenv('ARE_KHRONOS_KTX_BINARY')
        if not binary:
            self.skipTest('Real Khronos KTX binary required; dedicated KTX workflow runs this test')
        from software_gpu.tests.fixtures.model_fixture import make_glb
        from tools.visual_asset_lab_native import render_native_asset_lab
        import numpy as np
        import tempfile
        with tempfile.TemporaryDirectory(prefix='are-ktx-native-pbr-') as tmp:
            root = Path(tmp)
            def embed_ktx(doc, data):
                while len(data) % 4:
                    data.append(0)
                start = len(data)
                data.extend(REAL_KHRONOS_KTX2)
                doc['bufferViews'].append(dict(buffer=0, byteOffset=start,
                                               byteLength=len(REAL_KHRONOS_KTX2)))
                image_index = len(doc['images'])
                doc['images'].append(dict(bufferView=len(doc['bufferViews'])-1,
                                          mimeType='image/ktx2'))
                doc['textures'][0] = dict(sampler=0,
                          extensions={'KHR_texture_basisu': {'source': image_index}})
                doc['extensionsUsed'] = ['KHR_texture_basisu']
                doc['extensionsRequired'] = ['KHR_texture_basisu']
                doc['buffers'][0]['byteLength'] = len(data)
            ident = make_glb(root/'original-ktx.glb', mutate=embed_ktx,
                             static=True, surface=True)
            control = make_glb(root/'reference-png.glb', static=True, surface=True)
            lic = root/'license.txt'
            lic.write_text('Original 16x16 RGBA test texture; CC0-1.0; KTX generated with Khronos 4.4.2\n')
            manifest = dict(source_glb=str(root/'original-ktx.glb'),
                source_sha256=ident['sha256'], source_bytes=ident['bytes'], lod='lod0',
                images=[dict(image_index=3, sha256=REAL_KTX_SHA256, license='CC0-1.0',
                             license_path=str(lic),
                             license_sha256=hashlib.sha256(lic.read_bytes()).hexdigest())],
                transcoder=dict(path=str(Path(binary).resolve()),
                                sha256=REAL_KTX_BINARY_SHA256,version='4.4.2'),
                budget=budget())
            receipt = convert_ktx2_glb(manifest, root/'converted')
            self.assertEqual(receipt['source_glb_sha256'], ident['sha256'])
            self.assertEqual(receipt['images'][0]['mip_levels'], 5)
            self.assertEqual(receipt['images'][0]['resident_level'], 0)
            self.assertEqual(receipt['images'][0]['source_sha256'], REAL_KTX_SHA256)
            converted = root/'converted'/'converted.glb'
            self.assertEqual(hashlib.sha256(converted.read_bytes()).hexdigest(),
                             receipt['converted_glb_sha256'])
            native = render_native_asset_lab([
                dict(id='source', path=str(root/'reference-png.glb'),
                     sha256=control['sha256'], bytes=control['bytes']),
                dict(id='ktx', path=str(converted),
                     sha256=receipt['converted_glb_sha256'], bytes=converted.stat().st_size)],
                root/'pbr', pixels=64, repeats=2,
                camera=dict(eye=[1.33,2.33,6],target=[1.33,2.33,3],
                            up=[0,1,0],fov_y_degrees=55,near=.1,far=12))
            self.assertEqual(len(native['assets']), 2)
            for item in native['assets']:
                self.assertEqual(item['renderer']['render_profile'],'pbr')
                self.assertTrue(item['renderer']['full_buffer_parity'])
            depth = [(root/'pbr'/i/'native-depth.f32le').read_bytes()
                     for i in ('source','ktx')]
            self.assertEqual(depth[0],depth[1], 'same geometry, different texture: depth must be identical')
            beauty = [(root/'pbr'/i/'native-rgba8.bin').read_bytes()
                      for i in ('source','ktx')]
            self.assertEqual(len(beauty[0]),len(beauty[1]))
            self.assertGreater(sum(a != b for a,b in zip(beauty[0],beauty[1])), 0,
                               'lossy KTX can change PBR beauty; do not claim byte parity')
            self.assertNotEqual(receipt['pbr_beauty_diff'],'byte_equal_guaranteed')
            self.assertEqual(receipt['float32_depth_diff'],
                             'not_measured_without_reference_render')

    def test_srgb_etc1s_metadata_and_only_base_mip_resident(self):
        item = inspect_ktx2(ktx2(w=8, h=8, levels=3), budget(), 'srgb')
        self.assertEqual(item['dimensions'], [8, 8])
        self.assertEqual(item['mip_levels'], 3)
        self.assertEqual(item['resident_level'], 0)
        self.assertEqual(item['resident_decoded_bytes'], 8 * 8 * 4)
        self.assertEqual(item['mip_decoded_bytes'], [256, 64, 16])
        self.assertEqual(item['color_space'], 'srgb')
        self.assertEqual(item['compression'], 'basis_lz_etc1s')

    def test_linear_texture_cannot_be_used_in_srgb_material(self):
        with self.assertRaisesRegex(ValueError, 'KTX2_COLOR_SPACE'):
            inspect_ktx2(ktx2(space='linear'), budget(), 'srgb')

    def test_non_ktx_bad_magic_fails_closed(self):
        with self.assertRaisesRegex(ValueError, 'KTX2_MAGIC'):
            inspect_ktx2(b'Not KTX' + ktx2()[7:], budget(), 'srgb')

    def test_mip_level_dimensions_bomb_and_budget(self):
        for content, reason in ((ktx2(w=8192), 'KTX2_DIMENSIONS'),
                                (ktx2(w=4, h=4, levels=5), 'KTX2_MIP_COUNT'),
                                (ktx2(w=16, h=16), 'KTX2_TEXTURE_BUDGET')):
            with self.subTest(reason=reason):
                b = budget(max_texture_bytes=100) if reason == 'KTX2_TEXTURE_BUDGET' else budget()
                with self.assertRaisesRegex(ValueError, reason):
                    inspect_ktx2(content, b, 'srgb')

    def test_overlapping_mip_index_is_rejected(self):
        content = bytearray(ktx2(levels=2))
        struct.pack_into('<Q', content, 80 + 24, struct.unpack_from('<Q', content, 80)[0])
        with self.assertRaisesRegex(ValueError, 'KTX2_MIP_OVERLAP'):
            inspect_ktx2(bytes(content), budget(), 'srgb')

    def test_short_mip_bad_color_model_and_unknown_scheme_rejected(self):
        content = bytearray(ktx2())
        struct.pack_into('<Q', content, 80 + 8, 1000)
        with self.assertRaisesRegex(ValueError, 'KTX2_LEVEL_RANGE'):
            inspect_ktx2(bytes(content), budget(), 'srgb')
        with self.assertRaisesRegex(ValueError, 'KTX2_COLOR_MODEL'):
            inspect_ktx2(ktx2(model=255), budget(), 'srgb')
        raw = bytearray(ktx2())
        struct.pack_into('<I', raw, 12 + 8 * 4, 55)
        with self.assertRaisesRegex(ValueError, 'KTX2_SUPERCOMPRESSION'):
            inspect_ktx2(bytes(raw), budget(), 'srgb')

    def test_opt_in_manifest_and_uri_source_fail_before_output(self):
        with tempfile.TemporaryDirectory() as root:
            d = Path(root)
            output = d / 'converted'
            with self.assertRaisesRegex(ValueError, 'KTX2_MANIFEST'):
                convert_ktx2_glb({'source_glb': 'https://example.com/unsafe.glb'}, output)
            self.assertFalse(output.exists())

    def test_no_undeclared_license_or_missing_transcoder(self):
        with tempfile.TemporaryDirectory() as root:
            d = Path(root)
            path = d / 'sample.glb'
            path.write_bytes(b'bad')
            manifest = {'source_glb': str(path), 'source_sha256': '0' * 64,
                        'source_bytes': 3, 'lod': 'lod0', 'images': [],
                        'transcoder': {'path': '/missing/ktx', 'sha256': '0' * 64,
                                       'version': '4.4.2'}, 'budget': budget()}
            with self.assertRaisesRegex(ValueError, 'KTX2_SOURCE_HASH'):
                convert_ktx2_glb(manifest, d / 'new')

    def test_trailing_unindexed_bytes_and_misaligned_sgd_rejected(self):
        raw = ktx2()
        # No opaque trailing bytes can slip into an otherwise bounded KTX2.
        with self.assertRaisesRegex(ValueError, 'KTX2_UNINDEXED_BYTES'):
            inspect_ktx2(raw + b'secret', budget(), 'srgb')
        altered = bytearray(raw)
        struct.pack_into('<Q', altered, 64, 1)  # Bad SGD offset.
        with self.assertRaisesRegex(ValueError, 'KTX2_SGD_RANGE'):
            inspect_ktx2(bytes(altered), budget(), 'srgb')

    def test_same_mip_payload_must_never_be_admitted_twice(self):
        raw = bytearray(ktx2(levels=2))
        struct.pack_into('<Q', raw, 80 + 24, struct.unpack_from('<Q', raw, 80)[0])
        with self.assertRaisesRegex(ValueError, 'KTX2_MIP_OVERLAP'):
            inspect_ktx2(bytes(raw), budget(), 'srgb')

    def test_expected_mip_memory_is_bounded_even_with_tiny_payload(self):
        # Claiming a tiny encoded chunk must not permit a dimension bomb.
        with self.assertRaisesRegex(ValueError, 'KTX2_PIXELS'):
            inspect_ktx2(ktx2(w=4096, h=4096, data_size=4),
                         budget(max_pixels=256), 'srgb')

    def test_transcoder_version_must_match_whole_version_token(self):
        from tools.ktx2_texture_admission import _native_binary
        with tempfile.TemporaryDirectory() as root:
            d = Path(root)
            executable = d / 'ktx'
            executable.write_text('#!/bin/sh\necho Khronos-KTX 4.4.20\n')
            executable.chmod(0o700)
            meta = dict(path=str(executable), sha256=hashlib.sha256(executable.read_bytes()).hexdigest(),
                        version='4.4.2')
            with self.assertRaisesRegex(ValueError, 'KTX2_TRANSCODER_VERSION'):
                _native_binary(meta)

    def test_unsupported_ktx_color_models_and_schemes_fail_closed(self):
        for model in (0, 255):
            with self.subTest(model=model):
                with self.assertRaisesRegex(ValueError, 'KTX2_COLOR_MODEL'):
                    inspect_ktx2(ktx2(model=model), budget(), 'srgb')


if __name__ == '__main__':
    unittest.main()
